113	// A major command line at column 0: `name   brief`.
114	void print_major(std::FILE* out, const char* name, const char* brief) {
115	  std::fprintf(out, "%-7s %s\n", name, brief);
116	}
117	
118	// A subcommand/target line, indented two under its command: `  name   brief`.
119	void print_sub(std::FILE* out, const char* name, const char* brief) {
120	  std::fprintf(out, "  %-9s %s\n", name, brief);
121	}
122	
123	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
124	void print_opt(std::FILE* out, const OptRow& o) {
125	  char left[96];
126	  std::snprintf(left, sizeof left, "%*s%s", o.indent, "", o.flag);
127	  if (o.tag[0])
128	    std::fprintf(out, "%-29s %s  %s\n", left, o.tag, o.brief);
129	  else
130	    std::fprintf(out, "%-29s %s\n", left, o.brief);
131	}
132	
133	// `run`: major line, the mode subcommands, then the option list (dev options
134	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
135	void print_run_block(std::FILE* out) {
136	  print_major(out, "run", "run one simulation");
137	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
138	  std::fputs("\n", out);
139	  for (const OptRow& o : kRunOpts) {
140	    if (o.dev && !is_dev_mode()) continue;
141	    print_opt(out, o);
142	  }
143	}
144	
145	void print_list_block(std::FILE* out) {
146	  print_major(out, "list", "list what is available");
147	  for (const TargetRow& t : kListTargets) {
148	    if (t.dev && !is_dev_mode()) continue;
149	    print_sub(out, t.name, t.brief);
150	  }
151	}
152	
153	void print_doctor_block(std::FILE* out) {
154	  print_major(out, "doctor", "check toolchain + fixtures are present");
155	}
156	
157	// Top-level `andesim --help`: the whole tree -- every major command, its
158	// subcommands, and run's full option list, so one screen shows everything.
159	void print_usage(std::FILE* out) {
160	  std::fputs("usage: andesim <command> [options] <ELF> [-- <engine args>]\n\n",
161	             out);
162	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
163	             out);
164	  print_run_block(out);
165	  std::fputs("\n", out);
166	  print_list_block(out);
167	  std::fputs("\n", out);
168	  print_doctor_block(out);
169	  std::fputs(
170	      "\n'andesim run --help' / 'andesim list --help' for per-command "
171	      "detail.\n",
172	      out);
173	}
174	
175	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
176	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
177	  if (sc.name == "run") { print_run_block(out); return; }
178	  if (sc.name == "list") { print_list_block(out); return; }
179	  if (sc.name == "doctor") { print_doctor_block(out); return; }
180	  // A Hidden/unfinished command: a stable usage line, no advertised detail.
181	  std::fprintf(out, "usage: andesim %.*s [args...]\n",
182	               static_cast<int>(sc.name.size()), sc.name.data());
183	}
