187	int main(int argc, char** argv) {
188	  using namespace andes_sim;
189	
190	  Cli cli = parse_cli(argc, argv);
191	  if (!cli.error.empty()) {
192	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
193	    return 2;
194	  }
195	
196	  if (cli.subcommand.empty()) {  // no command, or top-level -h
197	    if (cli.help) {
198	      print_usage(stdout);
199	      return 0;
200	    }
201	    print_usage(stderr);
202	    return 2;
203	  }
204	
205	  const Subcommand* sc = find(cli.subcommand);
206	  if (!sc) {
207	    std::fprintf(stderr, "andesim: unknown command '%s'\n\n",
208	                 cli.subcommand.c_str());
209	    print_usage(stderr);
210	    return 2;
211	  }
212	
213	  if (cli.help) {
214	    print_subcommand_help(*sc, stdout);
215	    return 0;
216	  }
217	
218	  if (cli.subcommand == "list") return cmd_list(cli);
219	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
220	  if (cli.subcommand == "run") return cmd_run(cli);
221	
222	  // Remaining subcommands stub out until their feature lands. Resolve the repo
223	  // root so the discovery path stays live and observable.
224	  std::string root;
225	  try {
226	    root = repo_root().string();
227	  } catch (const std::exception& e) {
228	    root = std::string("<unknown: ") + e.what() + ">";
229	  }
230	  std::fprintf(stderr, "andesim %s: not yet implemented (repo root: %s)\n",
231	               cli.subcommand.c_str(), root.c_str());
232	  return 3;
233	}
