41	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
42	                               int got_rc) {
43	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
44	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
45	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
46	  // to completion without ever hitting its ROI boundary -- the marker/pc
47	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
48	  // mistake; name the kind so the fix is obvious, not a bare exit code.
49	  if (got_rc == 0 && expect_rc == PlanOptions{}.expect_rc)
50	    m += " -- the " + s.role + " ran to completion without reaching its " +
51	         s.trigger.kind +
52	         " trigger boundary (the ROI never drained; check the ELF actually "
53	         "reaches the " +
54	         s.trigger.kind + ")";
55	  return m;
56	}
