203	PlanResult run_plan(const Plan& plan,
204	                    const std::vector<EngineDescriptor>& engines,
205	                    const PlanOptions& opts) {
206	  PlanResult res;
207	  if (plan.steps.empty()) {
208	    res.error = "plan has no steps";
209	    return res;
210	  }
211	
212	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
213	  std::string mmap_path = plan.mmap_path;
214	  const bool own_mmap = mmap_path.empty();
215	  if (own_mmap) {
216	    std::string err;
217	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
218	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
219	    if (mmap_path.empty()) {
220	      res.error = err;
221	      return res;
222	    }
223	  }
224	
225	  // A private dir for the threaded drain files.
226	  std::error_code ec;
227	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
228	  std::string tmpl = workdir.string();
229	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
230	  tbuf.push_back('\0');
231	  const char* made = ::mkdtemp(tbuf.data());
232	  if (!made) {
233	    if (own_mmap) ::unlink(mmap_path.c_str());
234	    res.error = "failed to create plan work dir";
235	    return res;
236	  }
237	  const std::string wd = made;
238	
239	  RuntimeCtx ctx;
240	  ctx.mmap_path = mmap_path;
241	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
242	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
243	  // linker script still uses only --mem-size, so the scratch page sits above
244	  // everything it can address.
245	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
246	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
247	
248	  std::string err;
249	  const std::vector<std::vector<std::string>> argvs =
250	      plan_argvs(plan, engines, wd, ctx, err);
251	  if (!err.empty()) {
252	    res.error = err;
253	  } else {
254	    for (size_t i = 0; i < argvs.size(); ++i) {
255	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
256	      if (r.spawn_failed) {
257	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
258	        break;
259	      }
260	      if (r.timed_out) {
261	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
262	                    std::to_string(opts.timeout_ms) + " ms";
263	        break;
264	      }
265	      if (r.rc != opts.expect_rc) {
266	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
267	        break;
268	      }
269	      const StateFile sf = read_state_file(state_path(wd, i));
270	      if (!sf.ok()) {
271	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
272	        break;
273	      }
274	      // cosim checkpoints (`<state_out>.ckpts` stream, cosim_redesign F3):
275	      // read them back now, before the workdir teardown deletes the file.
276	      std::vector<hybrid_state_v1> ckpts;
277	      const std::string stream_p = state_path(wd, i) + ".ckpts";
278	      if (fs::exists(stream_p, ec)) {
279	        StateStream cs = read_state_stream(stream_p);
280	        if (!cs.ok()) {
281	          res.error = "plan step " + std::to_string(i) + ": " + cs.error;
282	          break;
283	        }
284	        ckpts = std::move(cs.records);
285	      }
286	      res.phases.push_back(
287	          {sf.st.mcycle, sf.st.minstret, r.out, sf.st, std::move(ckpts)});
288	    }
289	  }
290	
291	  fs::remove_all(wd, ec);
292	  if (own_mmap) ::unlink(mmap_path.c_str());
293	  return res;
294	}
